// SISTEMA DE USUÁRIO
// ════════════════════════════════════════════════════════════════════
const GDIUserSystem={
  getCurrentUser(){return getCookie("root_id")||"anonymous";},
  loadUserData(){
    try{
      const user=this.getCurrentUser();
      const key=`gdi_user_${user}`;
      const data=localStorage.getItem(key);
      if(data){
        const parsed=JSON.parse(data);
        window.GDI_USER_DATA={notes:parsed.notes||{},progress:parsed.progress||{},prefs:parsed.prefs||{},user:user};
        return parsed;
      }else{
        window.GDI_USER_DATA={notes:{},progress:{},prefs:{},user:user};
      }
    }catch(err){window.GDI_USER_DATA={notes:{},progress:{},prefs:{},user:"anonymous"};}
  },
  saveUserData(){
    try{
      const user=window.GDI_USER_DATA?.user||this.getCurrentUser();
      const key=`gdi_user_${user}`;
      const data={user,notes:window.GDI_USER_DATA?.notes||{},progress:window.GDI_USER_DATA?.progress||{},prefs:window.GDI_USER_DATA?.prefs||{},timestamp:new Date().toISOString()};
      localStorage.setItem(key,JSON.stringify(data));
    }catch(err){}
  },
  addNote(path,text){
    if(!window.GDI_USER_DATA)this.loadUserData();
    if(!window.GDI_USER_DATA.notes[path])window.GDI_USER_DATA.notes[path]=[];
    const time=window._gdiPlayerInstance?.currentTime?.()??window._gdiPlayerInstance?.currentTime??0;
    window.GDI_USER_DATA.notes[path].push({text,timestamp:new Date().toISOString(),position:Math.floor(time)});
    this.saveUserData();
    showToast("✏️ Anotação salva!");
  },
  getNotes(path){
    if(!window.GDI_USER_DATA)this.loadUserData();
    return window.GDI_USER_DATA.notes[path]||[];
  },
  removeNote(path,idx){
    if(!window.GDI_USER_DATA)this.loadUserData();
    if(window.GDI_USER_DATA.notes[path]){window.GDI_USER_DATA.notes[path].splice(idx,1);this.saveUserData();}
  },
  saveProgress(path,currentTime,duration){
    if(!window.GDI_USER_DATA)this.loadUserData();
    window.GDI_USER_DATA.progress[path]={currentTime,duration,percentage:Math.floor(currentTime/duration*100),lastWatched:new Date().toISOString()};
    this.saveUserData();
  },
  getProgress(path){
    if(!window.GDI_USER_DATA)this.loadUserData();
    return window.GDI_USER_DATA.progress[path]||null;
  },
  getLastWatchedFile(){
    if(!window.GDI_USER_DATA)this.loadUserData();
    let lastFile=null,lastTime=null;
    for(const[file,prog]of Object.entries(window.GDI_USER_DATA.progress||{})){
      if(prog?.lastWatched){const t=new Date(prog.lastWatched);if(!lastTime||t>lastTime){lastTime=t;lastFile=file;}}}
    return lastFile?{file:lastFile,progress:window.GDI_USER_DATA.progress[lastFile]}:null;
  }
};

