function get_file(i,e,t){const n="file_path_"+i+e.modifiedTime,a=localStorage.getItem(n);if(a!=null)return t(a);$.get(i,function(c){localStorage.setItem(n,c);t(c)})}

async function fallback(i,e){
  if(e){
    const t=await getCookie("root_id")||"";
    $("#content").html('<div class="gdi-wrap"><div class="gdi-spinner-wrap" style="height:150px;" id="spinner"><div class="gdi-spinner"></div></div></div>');
    fetch("/0:fallback",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:i})}).then(n=>{if(!n.ok)throw new Error("Request failed");return n.json()}).then(n=>dispatchFileView(n,t)).catch(n=>{$("#content").html(renderErrorCard(n))});
  }else{return list(i,true);}
}

async function file(i){
  const e=await getCookie("root_id")||"";
  $("#content").html('<div class="gdi-wrap"><div class="gdi-spinner-wrap" style="height:150px;" id="spinner"><div class="gdi-spinner"></div></div></div>');
  fetch("",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({path:i})}).then(t=>{if(!t.ok)throw new Error("Request failed");return t.json()}).then(t=>dispatchFileView(t,e)).catch(t=>{$("#content").html(renderErrorCard(t))});
}

function dispatchFileView(i,e){
  const UI=window.UI||{},t=i.mimeType,n=i.fileExtension;
  if(t==="application/vnd.google-apps.folder"){window.location.href=window.location.pathname+"/";return}
  if(!n&&!t)return;
  const a=i.name,c=encodeURIComponent(a),l=formatFileSize(i.size),d=UI.second_domain_for_dl?UI.downloaddomain+i.link:window.location.origin+i.link,o=i.id;
  if(t&&GDOC_TYPES[t])file_workspace(a,l,t,d);
  else if(FILE_TYPES.video.includes(n)||t&&t.includes("video")){const s=i.thumbnailLink?i.thumbnailLink.replace("s220","s0"):UI.poster;file_video(a,c,l,s,d,t,o,e)}
  else if(FILE_TYPES.audio.includes(n)||t&&t.includes("audio"))file_audio(a,c,l,d,o,e);
  else if(FILE_TYPES.image.includes(n)||t&&t.includes("image"))file_image(a,c,l,d,o,e);
  else if(n==="pdf"||t&&t.includes("pdf"))file_pdf(a,c,l,d,o,e);
  else if(FILE_TYPES.code.includes(n))file_code(a,c,l,i.size,d,n,o,e);
  else file_others(a,c,l,d,o,e);
}

