function file_video(i,e,t,n,a,c,l,d,o){
  const UI=window.UI||{},player_config=window.player_config||{};
  o=o||[];
  const s=a.includes(".m3u8")||c==="application/x-mpegURL";
  let r="",p="",g="";
  
  if(!UI.disable_player){
    if(player_config.player==="plyr"){
      r=`<video id="player" playsinline controls autoplay muted data-poster="${n}"><source src="${a}" type="${s?"application/x-mpegURL":"video/mp4"}">${o.map(h=>`<track kind="subtitles" src="${escHtml(h.url)}" label="${escHtml(h.label)}" default>`).join("")}</video>`;
      p="https://cdn.plyr.io/"+player_config.plyr_io_version+"/plyr.polyfilled.js";
      g="https://cdn.plyr.io/"+player_config.plyr_io_version+"/plyr.css";
    }else if(player_config.player==="videojs"){
      r=`<video id="vplayer" poster="${n}" class="video-js vjs-default-skin vjs-big-play-centered" controls autoplay muted preload="auto" width="100%" height="100%" data-setup='{"fluid":true,"autoplay":true,"muted":true}'><source src="${a}" type="${s?"application/x-mpegURL":"video/mp4"}"><source src="${a}" type="video/webm">${o.map(h=>`<track kind="subtitles" src="${escHtml(h.url)}" label="${escHtml(h.label)}" default>`).join("")}</video>`;
      p="https://vjs.zencdn.net/"+player_config.videojs_version+"/video.js";
      g="https://vjs.zencdn.net/"+player_config.videojs_version+"/video-js.css";
    }else if(player_config.player==="dplayer"){
      r='<div id="player-container"></div>';
      p="https://cdn.jsdelivr.net/npm/dplayer/dist/DPlayer.min.js";
      g="https://cdn.jsdelivr.net/npm/dplayer/dist/DPlayer.min.css";
    }else if(player_config.player==="jwplayer"){
      r='<div id="player"></div>';
      p="https://content.jwplatform.com/libraries/IDzF9Zmk.js";
    }
  }

  // Player body com botões de navegação e playlist
  const f=`<div class="gdi-player-wrap" style="width:100%;margin:0 auto;">${r}</div>
<div id="gdi-player-nav" style="display:none;justify-content:space-between;align-items:center;margin-top:10px;gap:8px;">
  <button id="gdi-btn-prev" class="gdi-btn gdi-btn-ghost" style="flex:1;" title="Anterior"><i class="bi bi-skip-start-fill"></i> Anterior</button>
  <span id="gdi-nav-info" style="font-size:12px;color:var(--gdi-text-muted,#aaa);white-space:nowrap;"></span>
  <button id="gdi-btn-next" class="gdi-btn gdi-btn-ghost" style="flex:1;justify-content:flex-end;" title="Próxima">Próxima <i class="bi bi-skip-end-fill"></i></button>
</div>
<div id="gdi-player-controls" style="display:flex;gap:8px;margin-top:10px;">
  <button id="gdi-toggle-notes" class="gdi-btn gdi-btn-ghost" style="flex:1;"><i class="bi bi-pencil-square"></i> Anotações</button>
</div>
<div id="gdi-playlist-wrap" style="margin-top:16px;display:none;">
  <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:8px;">
    <strong style="font-size:14px;"><i class="bi bi-collection-play me-2"></i>Playlist</strong>
    <span id="gdi-playlist-count" style="font-size:12px;color:var(--gdi-text-muted,#aaa);"></span>
  </div>
  <div id="gdi-playlist-list" style="max-height:260px;overflow-y:auto;border:1px solid rgba(255,255,255,0.12);border-radius:8px;padding:6px;background:rgba(0,0,0,0.2);"></div>
</div>`;

  const u=UI.disable_video_download?"":renderDownloadButtons(a,e,{showMedia:true});
  $("#content").html(_viewerCard('<i class="bi bi-camera-video-fill gdi-icon-video"></i>',i,t,f,u));
  $(".gdi-viewer").css({"max-width":"1200px","width":"96%","margin":"0 auto"});

  if(g){const h=document.createElement("link");h.rel="stylesheet";h.href=g;document.head.appendChild(h);}
  window._gdiPlayerInstance=null;

  function initPlayerEvents(){
    if(player_config.player==="plyr"){
      const m=new Plyr("#player",{autoplay:true,keyboard:{focused:true,global:true}});
      window._gdiPlayerInstance=m;
      m.on("ready",()=>{m.play().catch(()=>{});setTimeout(()=>{m.muted=false;},2000);});
      m.on("ended",playNextInPlaylist);
      m.on("pause",()=>{GDIUserSystem.saveProgress(window.location.pathname,m.currentTime,m.duration);});
      setInterval(()=>{if(m&&m.duration){GDIUserSystem.saveProgress(window.location.pathname,m.currentTime,m.duration);}},5000);
    }else if(player_config.player==="videojs"){
      const m=videojs("vplayer",{autoplay:true,playbackRates:[.5,.75,1,1.25,1.5,2],controlBar:{pictureInPictureToggle:true}});
      window._gdiPlayerInstance=m;
      m.ready(function(){
        this.play().catch(()=>{});
        setTimeout(()=>{this.muted(false);},2000);
        this.on("ended",()=>{playNextInPlaylist();});
        this.on("pause",()=>{GDIUserSystem.saveProgress(window.location.pathname,this.currentTime(),this.duration());});
        setInterval(()=>{if(this&&this.duration()){GDIUserSystem.saveProgress(window.location.pathname,this.currentTime(),this.duration());}},5000);
      });
    }else if(player_config.player==="dplayer"){
      const m=new DPlayer({container:document.getElementById("player-container"),autoplay:true,muted:true,screenshot:true,video:{url:a,pic:n,type:s?"hls":"auto"},subtitle:o.length?{url:o[0].url,type:"webvtt"}:undefined});
      setTimeout(()=>{m.volume(0.5);},2000);
      window._gdiPlayerInstance=m;
      m.play();
      m.on("ended",playNextInPlaylist);
      setInterval(()=>{if(m&&m.video){GDIUserSystem.saveProgress(window.location.pathname,m.video.currentTime,m.video.duration);}},5000);
    }else if(player_config.player==="jwplayer"){
      const m=jwplayer("player").setup({file:a,type:c,autostart:true,mute:true,image:n,width:"100%",aspectratio:"16:9",title:i,description:"Powered by Google Drive Index",tracks:o.map(v=>({file:v.url,kind:"captions",label:v.label,default:true})),captions:{color:"#f3f378",fontSize:14,backgroundOpacity:50,edgeStyle:"raised"}});
      setTimeout(()=>{m.setMute(false);},2000);
      window._gdiPlayerInstance=m;
      m.on("complete",playNextInPlaylist);
      setInterval(()=>{const v=m.getPosition();const w=m.getDuration();if(v>=0&&w>0){GDIUserSystem.saveProgress(window.location.pathname,v,w);}},5000);
    }
  }

  if(p){
    if(window.Plyr||window.videojs||window.DPlayer||window.jwplayer){initPlayerEvents();}
    else{const h=document.createElement("script");h.src=p;h.onload=()=>{initPlayerEvents();};document.head.appendChild(h);}
  }

  initNotesUI();
  document.getElementById("gdi-toggle-notes")?.addEventListener("click",()=>{
    const b=document.getElementById("gdi-notes-panel");
    if(b){b.style.display=b.style.display==="none"?"block":"none";}
  });

  let playlistVideos=[],currentIndex=-1;

  function renderPlaylistUI(){
    if(!playlistVideos.length)return;
    let h="";
    playlistVideos.forEach((m,v)=>{
      const w=v===currentIndex;
      const y=w?"background:var(--bs-primary,#1f6feb);color:#fff;":"background:rgba(255,255,255,0.05);color:var(--gdi-text,#e6edf3);";
      h+=`<div class="gdi-playlist-item" data-idx="${v}" style="padding:8px 12px;margin:3px 0;border-radius:6px;cursor:pointer;display:flex;align-items:center;justify-content:space-between;font-size:13px;${y}"><div style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:80%;"><i class="bi bi-${w?"play-fill":"film"} me-2"></i><span>${escHtml(m.name)}</span></div><span style="font-size:11px;opacity:0.8;">${m.size||""}</span></div>`;
    });
    $("#gdi-playlist-list").html(h);
    $("#gdi-playlist-count").text(`${currentIndex+1} / ${playlistVideos.length}`);
    $("#gdi-playlist-wrap").show();
    
    const navBar=document.getElementById("gdi-player-nav");
    if(navBar&&playlistVideos.length>1){
      navBar.style.display="flex";
      document.getElementById("gdi-nav-info").textContent=`${currentIndex+1} / ${playlistVideos.length}`;
      const prevBtn=document.getElementById("gdi-btn-prev");
      const nextBtn=document.getElementById("gdi-btn-next");
      prevBtn.disabled=currentIndex<=0;
      prevBtn.style.opacity=currentIndex<=0?"0.4":"1";
      nextBtn.disabled=currentIndex>=playlistVideos.length-1;
      nextBtn.style.opacity=currentIndex>=playlistVideos.length-1?"0.4":"1";
    }
    
    $(".gdi-playlist-item").off("click").on("click",function(){
      const m=parseInt($(this).data("idx"));
      if(!isNaN(m)&&playlistVideos[m])switchVideo(m);
    });
  }

  document.getElementById("gdi-btn-prev")?.addEventListener("click",()=>{
    if(currentIndex>0)switchVideo(currentIndex-1);
  });
  document.getElementById("gdi-btn-next")?.addEventListener("click",()=>{
    if(currentIndex<playlistVideos.length-1)switchVideo(currentIndex+1);
  });

  function switchVideo(h){
    if(h<0||h>=playlistVideos.length)return;
    currentIndex=h;
    const m=playlistVideos[currentIndex];
    if(m.pageUrl)history.pushState(null,m.name,m.pageUrl);
    $(".gdi-file-header-name").text(m.name);
    $(".gdi-file-header-meta").text(m.size);
    const v=window.drive_names?window.drive_names[window.current_drive_order||0]:"Drive";
    $("title").html(`${v} - ${m.name}`);
    if(!UI.disable_video_download)$(".gdi-viewer-footer").html(renderDownloadButtons(m.streamUrl,encodeURIComponent(m.name),{showMedia:true}));
    
    if(player_config.player==="plyr"&&window._gdiPlayerInstance){
      window._gdiPlayerInstance.source={type:"video",title:m.name,sources:[{src:m.streamUrl,type:m.streamUrl.includes(".m3u8")||m.mimeType==="application/x-mpegURL"?"application/x-mpegURL":"video/mp4"}]};
      window._gdiPlayerInstance.play().catch(()=>{});
    }else if(player_config.player==="videojs"&&window._gdiPlayerInstance){
      window._gdiPlayerInstance.src({src:m.streamUrl,type:m.streamUrl.includes(".m3u8")||m.mimeType==="application/x-mpegURL"?"application/x-mpegURL":"video/mp4"});
      window._gdiPlayerInstance.play().catch(()=>{});
    }else if(player_config.player==="dplayer"&&window._gdiPlayerInstance){
      window._gdiPlayerInstance.switchVideo({url:m.streamUrl,pic:m.poster,type:m.streamUrl.includes(".m3u8")||m.mimeType==="application/x-mpegURL"?"hls":"auto"});
      window._gdiPlayerInstance.play();
    }else if(player_config.player==="jwplayer"&&window._gdiPlayerInstance){
      window._gdiPlayerInstance.load([{file:m.streamUrl,type:m.mimeType,image:m.poster,title:m.name}]);
      window._gdiPlayerInstance.play();
    }else{
      const w=document.getElementById("player")||document.getElementById("vplayer");
      if(w){w.src=m.streamUrl;w.play().catch(()=>{});}
    }
    renderPlaylistUI();
  }

  function playNextInPlaylist(){
    if(currentIndex>=0&&currentIndex<playlistVideos.length-1)switchVideo(currentIndex+1);
  }

  const currentPath=window.location.pathname;
  const folderPath=currentPath.split("/").slice(0,-1).join("/")+"/";
  const parentPath=currentPath.split("/").slice(0,-2).join("/")+"/";

  function buildPlaylistFromFiles(files,basePath,folderLabel){
    const videos=[];
    files.forEach(v=>{
      if(FILE_TYPES.video.includes(v.fileExtension)||v.mimeType&&v.mimeType.includes("video")){
        const w=encodeURIComponent(v.name);
        const y=UI.second_domain_for_dl?UI.downloaddomain+v.link:window.location.origin+v.link;
        const _=basePath+w+"?a=view";
        const b=v.thumbnailLink?v.thumbnailLink.replace("s220","s0"):UI.poster;
        videos.push({id:v.id,name:v.name,folderLabel:folderLabel||null,size:formatFileSize(v.size),streamUrl:y,pageUrl:_,mimeType:v.mimeType,poster:b,folder:basePath});
      }
    });
    return videos;
  }

  async function loadCrossFolderPlaylist(){
    return new Promise((resolve)=>{
      requestListPath(parentPath,{},function(parentData){
        if(!parentData||!parentData.data||!parentData.data.files){resolve([]);return;}
        const subFolders=parentData.data.files.filter(f=>f.mimeType==="application/vnd.google-apps.folder");
        if(!subFolders.length){resolve([]);return;}
        subFolders.sort((a,b)=>a.name.localeCompare(b.name,undefined,{numeric:true,sensitivity:'base'}));
        const allVideos=[];
        let done=0;
        subFolders.forEach(folder=>{
          const fpath=parentPath+encodeURIComponent(folder.name)+"/";
          requestListPath(fpath,{},function(folderData){
            if(folderData&&folderData.data&&folderData.data.files){
              const vids=buildPlaylistFromFiles(folderData.data.files,fpath,folder.name);
              if(vids.length>0)allVideos.push({sortKey:folder.name,folderName:folder.name,video:vids[0]});
            }
            done++;
            if(done===subFolders.length){
              allVideos.sort((a,b)=>a.sortKey.localeCompare(b.sortKey,undefined,{numeric:true,sensitivity:'base'}));
              const videos=allVideos.map(x=>x.video);
              if(videos.length>1){
                const nameCounts={};
                videos.forEach(v=>{nameCounts[v.name]=(nameCounts[v.name]||0)+1;});
                const maxCount=Math.max(...Object.values(nameCounts));
                if(maxCount/videos.length>0.3){
                  allVideos.forEach((item,idx)=>{
                    const num=String(idx+1).padStart(3,'0');
                    item.video.name=num+' - '+item.folderName;
                  });
                }
              }
              resolve(videos);
            }
          },null,3,false);
        });
      },null,3,false);
    });
  }

  requestListPath(folderPath,{},async function(h){
    if(!h||!h.data||!h.data.files)return;
    const m=h.data.files;
    let videos=buildPlaylistFromFiles(m,folderPath);

    if(videos.length<=1){
      const crossVideos=await loadCrossFolderPlaylist();
      if(crossVideos.length>1){
        playlistVideos=crossVideos;
        currentIndex=playlistVideos.findIndex(v=>v.name===i||v.streamUrl===a);
        if(currentIndex===-1){
          playlistVideos.unshift({name:i,size:t,streamUrl:a,pageUrl:window.location.href,mimeType:c,poster:n,folder:folderPath});
          currentIndex=0;
        }
        renderPlaylistUI();
        return;
      }
    }

    playlistVideos=videos;
    currentIndex=playlistVideos.findIndex(v=>v.name===i||v.streamUrl===a);
    if(currentIndex===-1&&playlistVideos.length>0){
      playlistVideos.unshift({name:i,size:t,streamUrl:a,pageUrl:window.location.href,mimeType:c,poster:n,folder:folderPath});
      currentIndex=0;
    }
    renderPlaylistUI();
  },null,3,false);
}

function file_audio(i,e,t,n,a,c,l){
  const UI=window.UI||{};
  l=l||[{name:i,url:n,cover:UI.audioposter}];
  const d=UI.disable_player?"":'<div id="aplayer-container" style="max-width:680px;margin:0 auto;"></div>';
  const o=UI.disable_audio_download?"":renderDownloadButtons(n,e,{showMedia:!0});
  $("#content").html(_viewerCard('<i class="bi bi-music-note-beamed gdi-icon-audio"></i>',i,t,d,o));
  if(UI.disable_player)return;
  const s=document.createElement("link");s.rel="stylesheet";s.href="https://cdn.jsdelivr.net/npm/aplayer@1.10.1/dist/APlayer.min.css";document.head.appendChild(s);
  const r=document.createElement("script");r.src="https://cdn.jsdelivr.net/npm/aplayer@1.10.1/dist/APlayer.min.js";
  r.onload=function(){window._gdiAPlayer=new APlayer({container:document.getElementById("aplayer-container"),mini:!1,autoplay:!1,theme:"#4d9fec",loop:"all",order:"list",preload:"auto",volume:.7,listFolded:!1,audio:l});};
  document.head.appendChild(r);
}

function file_pdf(i,e,t,n,a,c){
  const l=`<div class="gdi-wrap"><div class="gdi-viewer"><div class="gdi-breadcrumb-wrap"><ol class="gdi-bc">${_viewerBreadcrumb()}</ol></div><div class="gdi-viewer-card"><div class="gdi-file-header"><span class="gdi-file-header-icon"><i class="bi bi-file-earmark-pdf-fill gdi-icon-pdf"></i></span><div class="gdi-file-header-info"><div class="gdi-file-header-name">${escHtml(i)}</div><div class="gdi-file-header-meta">${escHtml(t)}</div></div></div><div class="gdi-viewer-body no-pad"><div class="gdi-pdf-controls"><button id="pdf-prev" class="gdi-btn gdi-btn-ghost gdi-btn-icon"><i class="bi bi-chevron-left"></i></button><span style="font-size:13px;color:var(--gdi-text-muted);">Page <span id="pdf-page-num">1</span> / <span id="pdf-page-count">?</span></span><button id="pdf-next" class="gdi-btn gdi-btn-ghost gdi-btn-icon"><i class="bi bi-chevron-right"></i></button><input id="pdf-zoom" type="range" min="50" max="200" value="100" style="width:100px;"><span id="pdf-zoom-val">100%</span></div><div style="padding:16px;"><div id="pdf-spinner" class="gdi-spinner-wrap"><div class="gdi-spinner"></div></div><canvas id="pdf-canvas" style="max-width:100%;display:block;margin:auto;"></canvas></div></div><div class="gdi-viewer-footer">${renderDownloadButtons(n,e)}</div></div></div></div>`;
  $("#content").html(l);
  let d=null,o=1,s=1;
  function r(){
    const p=document.getElementById("pdf-canvas"),g=p.getContext("2d");
    pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.worker.min.js";
    function f(u){d.getPage(u).then(function(h){const m=h.getViewport({scale:s});p.height=m.height;p.width=m.width;h.render({canvasContext:g,viewport:m}).promise.then(function(){$("#pdf-spinner").hide()});document.getElementById("pdf-page-num").textContent=u;});}
    pdfjsLib.getDocument(n).promise.then(function(u){d=u;document.getElementById("pdf-page-count").textContent=u.numPages;f(o);}).catch(function(u){$("#pdf-spinner").html(`<div class="gdi-alert gdi-alert-error">Could not load PDF: ${u.message}</div>`);});
    document.getElementById("pdf-prev").addEventListener("click",function(){o>1&&(o--,f(o));});
    document.getElementById("pdf-next").addEventListener("click",function(){d&&o<d.numPages&&(o++,f(o));});
    document.getElementById("pdf-zoom").addEventListener("input",function(){s=parseInt(this.value)/100;document.getElementById("pdf-zoom-val").textContent=this.value+"%";f(o);});
  }
  if(typeof pdfjsLib!=="undefined")r();
  else{const p=document.createElement("script");p.src="https://cdn.jsdelivr.net/npm/pdfjs-dist@3.11.174/build/pdf.min.js";p.onload=r;document.head.appendChild(p);}
}

function file_image(i,e,t,n,a,c){
  const l=`<div class="gdi-wrap"><div class="gdi-viewer"><div class="gdi-breadcrumb-wrap"><ol class="gdi-bc">${_viewerBreadcrumb()}</ol></div><div class="gdi-viewer-card"><div class="gdi-file-header"><span class="gdi-file-header-icon"><i class="bi bi-image gdi-icon-image"></i></span><div class="gdi-file-header-info"><div class="gdi-file-header-name">${escHtml(i)}</div><div class="gdi-file-header-meta">${escHtml(t)}</div></div></div><div class="gdi-viewer-body no-pad"><div class="gdi-img-wrap"><img src="${n}" alt="${escHtml(i)}" loading="lazy"></div></div><div class="gdi-viewer-footer">${renderDownloadButtons(n,e)}</div></div></div></div>`;
  $("#content").html(l);
}

function formatDateTime(i){return i?new Date(i).toLocaleString():""}
const utc2delhi=formatDateTime;

function formatFileSize(i){const e=Number(i);return isNaN(e)||e<0?"":e>=1099511627776?(e/1099511627776).toFixed(2)+" TB":e>=1073741824?(e/1073741824).toFixed(2)+" GB":e>=1048576?(e/1048576).toFixed(2)+" MB":e>=1024?(e/1024).toFixed(2)+" KB":e>1?e+" bytes":e===1?"1 byte":"0 bytes"}

function markdown(i,e){const t=marked.parse(e);$(i).show().html(t)}

async function getCookie(i){const e=i+"=",t=document.cookie.split(";");for(let n=0;n<t.length;n++){let a=t[n];while(a.charAt(0)==" ")a=a.substring(1);if(a.indexOf(e)==0)return a.substring(e.length);}return null}

document.addEventListener("change",function(i){if(i.target&&i.target.id==="select-all-checkboxes"){document.querySelectorAll("input.gdi-row-check").forEach(t=>{t.checked=i.target.checked;});}});

window.onpopstate=function(){render(window.location.pathname)};

function fetchQuota(){const i=window.current_drive_order||0;fetch(`/${i}:quota`).then(e=>{if(!e.ok)throw new Error("quota fetch failed");return e.json()}).then(e=>{const t=e.storageQuota;if(!t)return;const n=Number(t.usage||0),a=Number(t.limit||0),c=document.getElementById("gdi-quota-bar"),l=document.getElementById("gdi-quota-text"),d=document.getElementById("gdi-quota-fill");if(!c||!l||!d)return;const o=a>0?Math.min(100,n/a*100):0,s=o>90?"#f44336":o>70?"#ff9800":"#4caf50";l.textContent=a>0?`${formatFileSize(n)} used of ${formatFileSize(a)} (${o.toFixed(1)}%)`:`${formatFileSize(n)} used`;d.style.width=o+"%";d.style.background=s;c.style.display="block";}).catch(()=>{});}

$(function(){
  GDIUserSystem.loadUserData();
  init();
  window.UI?.show_quota&&fetchQuota();
  new URLSearchParams(window.location.search).get("embed")==="1"&&document.body.classList.add("embed-mode");
  render(window.location.pathname);
});

